'use strict';

// MODULES //

var tape = require( 'tape' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var Complex64Array = require( '@stdlib/array/complex64' );
var isSameComplex64 = require( '@stdlib/assert/is-same-complex64' );
var cdotu = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cdotu, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 7', function test( t ) {
	t.strictEqual( cdotu.length, 7, 'returns expected value' );
	t.end();
});

tape( 'the function calculates the dot product of two single-precision complex floating-point vectors `x` and `y`', function test( t ) {
	var dot;
	var x;
	var y;

	x = new Complex64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 2.0, -5.0, 6.0 ] );
	y = new Complex64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 8.0, 2.0, -3.0 ] );

	dot = cdotu( x.length, x, 1, 0, y, 1, 0 );
	t.strictEqual(isSameComplex64( dot, new Complex64( 3, 70 ) ), true, 'returns expected value' );

	x = new Complex64Array( [ 3.0, -4.0, 1.0, 2.0 ] );
	y = new Complex64Array( [ 1.0, -2.0, 3.0, 8.0 ] );

	dot = cdotu( x.length, x, 1, 0, y, 1, 0 );
	t.strictEqual( isSameComplex64( dot, new Complex64( -18, 4 ) ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the function returns `0`', function test( t ) {
	var dot;
	var x;
	var y;

	x = new Complex64Array( [ 3.0, -4.0, 1.0, 7.0 ] );
	y = new Complex64Array( [ 1.0, -2.0, 3.0, -3.0 ] );

	dot = cdotu( 0, x, 1, 0, y, 1, 0 );
	t.strictEqual( isSameComplex64( dot, new Complex64( 0, 0 ) ), true, 'returns expected value' );

	dot = cdotu( -4, x, 1, 0, y, 1, 0 );
	t.strictEqual( isSameComplex64( dot, new Complex64( 0, 0 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports an `x` stride', function test( t ) {
	var dot;
	var x;
	var y;

	x = new Complex64Array([
		2.0,  // 0
		-3.0, // 0
		-5.0,
		6.0,
		7.0,  // 1
		6.0   // 1
	]);
	y = new Complex64Array([
		8.0,  // 0
		2.0,  // 0
		-3.0, // 1
		3.0,  // 1
		-4.0,
		1.0
	]);

	dot = cdotu( 2, x, 2, 0, y, 1, 0 );
	t.strictEqual( isSameComplex64( dot, new Complex64( -17, -17 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports an `x` offset', function test( t ) {
	var dot;
	var x;
	var y;

	x = new Complex64Array([
		2.0,
		-3.0,
		-5.0, // 0
		6.0,  // 0
		7.0,  // 1
		6.0   // 1
	]);
	y = new Complex64Array([
		8.0,  // 0
		2.0,  // 0
		-3.0, // 1
		3.0,  // 1
		-4.0,
		1.0
	]);

	dot = cdotu( 2, x, 1, 1, y, 1, 0 );
	t.strictEqual( isSameComplex64( dot, new Complex64( -91, 41 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports a `y` stride', function test( t ) {
	var dot;
	var x;
	var y;

	x = new Complex64Array([
		2.0,  // 0
		-3.0, // 0
		-5.0, // 1
		6.0,  // 1
		7.0,
		6.0
	]);
	y = new Complex64Array([
		8.0,  // 0
		2.0,  // 0
		-3.0,
		3.0,
		-4.0, // 1
		1.0   // 1
	]);

	dot = cdotu( 2, x, 1, 0, y, 2, 0 );
	t.strictEqual( isSameComplex64( dot, new Complex64( 36, -49 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports a `y` offset', function test( t ) {
	var dot;
	var x;
	var y;

	x = new Complex64Array([
		1.0, // 0
		2.0, // 0
		3.0,
		4.0,
		5.0, // 1
		6.0  // 1
	]);
	y = new Complex64Array([
		7.0,
		8.0,
		9.0,  // 0
		10.0, // 0
		11.0, // 1
		12.0  // 1
	]);

	dot = cdotu( 2, x, 2, 0, y, 1, 1 );
	t.strictEqual( isSameComplex64( dot, new Complex64( -28, 154 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports negative strides', function test( t ) {
	var dot;
	var x;
	var y;

	x = new Complex64Array([
		1.0, // 1
		2.0, // 1
		3.0,
		4.0,
		5.0, // 0
		6.0  // 0
	]);
	y = new Complex64Array([
		7.0,
		8.0,
		9.0,  // 1
		10.0, // 1
		11.0, // 0
		12.0  // 0
	]);

	dot = cdotu( 2, x, -2, x.length-1, y, -1, 2 );
	t.strictEqual( isSameComplex64( dot, new Complex64( -28, 154 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports complex access patterns', function test( t ) {
	var dot;
	var x;
	var y;

	x = new Complex64Array([
		1.0, // 0
		2.0, // 0
		3.0,
		4.0,
		5.0, // 1
		6.0  // 1
	]);
	y = new Complex64Array([
		7.0,  // 1
		8.0,  // 1
		9.0,  // 0
		10.0, // 0
		11.0,
		12.0
	]);

	dot = cdotu( 2, x, 2, 0, y, -1, y.length-2 );
	t.strictEqual( isSameComplex64( dot, new Complex64( -24, 110 ) ), true, 'returns expected value' );
	t.end();
});
